const navbar=document.getElementById('navbar');window.addEventListener('scroll',()=>{if(window.scrollY>50)navbar.classList.add('scrolled');else navbar.classList.remove('scrolled')});const hamburger=document.getElementById('hamburger'),navLinks=document.getElementById('navLinks');hamburger.addEventListener('click',()=>{hamburger.classList.toggle('active');navLinks.classList.toggle('active')});const statNumbers=document.querySelectorAll('.stat-number');let counted=false;const countUp=(el)=>{const target=+el.getAttribute('data-target');let count=0;const inc=target/50;const updateCount=()=>{if(count<target){count+=inc;el.textContent=Math.ceil(count);setTimeout(updateCount,40);}else{el.textContent=target;}};updateCount();};const observer=new IntersectionObserver((entries)=>{entries.forEach(entry=>{if(entry.isIntersecting&&!counted){statNumbers.forEach(n=>countUp(n));counted=true;}});},{threshold:0.5});statNumbers.forEach(n=>observer.observe(n));</script></body></html>
